:root {

    --color-primary: #1a1a2e; 
    --color-secondary: #00bcd4; 
    --color-accent: #ffeb3b; 
    --color-text: #f0f0d8; 
    --color-background: #2c3e50; 


    --font-family: 'Courier New', monospace, system-ui, -apple-system, Roboto, sans-serif;
    --spacing-unit: 1rem;
    --padding-base: 0.5rem 1rem;


    --radius-sm: 4px;
    --shadow-box: 3px 3px 0 0 var(--color-primary); 
    --transition-speed: 0.15s;
}
*, *::before, *::after {
    box-sizing: border-box;
}
body {
    margin: 0;
    padding: 0;
    background-color: var(--color-primary);
    color: var(--color-text);
    font-family: var(--font-family);
    line-height: 1.6;
}
.container {
    max-width: 900px;
    margin: 0 auto;
    padding: var(--spacing-unit) calc(2 * var(--spacing-unit));
}
h1, h2, h3 {
    color: var(--color-secondary);
    font-size: 1.8rem;
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    padding-bottom: 0.25rem;
    border-bottom: 3px solid var(--color-secondary); 
    display: inline-block;
}
h1 { font-size: 2.5rem; }
h2 { font-size: 2rem; }
h3 { font-size: 1.5rem; color: var(--color-accent); border-bottom: none;}
p {
    margin-bottom: 1rem;
}
a {
    color: var(--color-secondary);
    text-decoration: underline;
    transition: color var(--transition-speed);
}
a:hover {
    color: var(--color-accent);
    text-decoration: none;
}
.btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    background-color: var(--color-secondary);
    color: var(--color-primary); 
    border: none;
    cursor: pointer;
    font-family: inherit;
    text-transform: uppercase;
    letter-spacing: 1px;
    box-shadow: var(--shadow-box);
    transition: all var(--transition-speed) ease;
}
.btn:hover {
    background-color: var(--color-accent);
    color: var(--color-primary);

    transform: translate(1px, 1px);
    box-shadow: none;
}

