site-header.css:
#site-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 2rem; 
    background-color: var(--color-primary);
    border-bottom: 4px solid var(--color-secondary);
}
#site-header .brand {
    font-size: 2.5rem;
    color: var(--color-accent);
    text-shadow: 3px 3px 0 0 var(--color-primary); 
}
