#juego {
    padding-bottom: 3rem;
}
#juego h2 {
    border-bottom: none; 
    margin-top: 0;
}
#juego #game-board-wrapper {
    background-color: var(--color-background);
    padding: 1rem;
    border: 4px solid var(--color-secondary);
    box-shadow: var(--shadow-box), inset 0 0 10px rgba(0, 0, 0, 0.5);

    display: block; 
}
#juego .map-grid {
    display: grid;
    gap: 1px;
    background-color: #000; 
    border: 2px solid var(--color-secondary);

